/** Parkhaustarif: Stundenpreis, Tageshöchstpreis und Freiminuten, alles in Cent bzw. Minuten. */
export interface Tarif {
  stundenpreis: number;
  tageshoechstpreis: number;
  freiminuten: number;
}

export class TarifFormatError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "TarifFormatError";
  }
}

function zahl(daten: Record<string, unknown>, feld: string): number {
  const wert = daten[feld];
  if (typeof wert !== "number" || !Number.isFinite(wert) || wert < 0) {
    throw new TarifFormatError(`${feld} fehlt oder ist keine Zahl >= 0: ${String(wert)}`);
  }
  return wert;
}

/** Tarif aus dem JSON der Verwaltung; wirft bei unlesbarem JSON und bei ungültigen Feldern. */
export function parseTarif(text: string): Tarif {
  const daten = JSON.parse(text) as Record<string, unknown>;
  const tarif = {
    stundenpreis: zahl(daten, "stundenpreis"),
    tageshoechstpreis: zahl(daten, "tageshoechstpreis"),
    freiminuten: zahl(daten, "freiminuten"),
  };
  if (tarif.tageshoechstpreis < tarif.stundenpreis) {
    throw new TarifFormatError("Tageshöchstpreis liegt unter dem Stundenpreis");
  }
  return tarif;
}

