import { readFileSync } from "fs";

import { parseTarif, Tarif } from "../lib/tarif";

/** Gilt, solange die Verwaltung keinen gültigen Tarif hinterlegt hat. */
export const STANDARDTARIF: Tarif = {
  stundenpreis: 250,
  tageshoechstpreis: 1800,
  freiminuten: 15,
};

/** Tarif aus der Datei der Verwaltung; fehlt sie oder ist sie ungültig, der Standardtarif. */
export function ladeTarif(pfad: string): Tarif {
  let text: string;
  try {
    text = readFileSync(pfad, "utf-8");
  } catch {
    return STANDARDTARIF;
  }
  try {
    return parseTarif(text);
  } catch (fehler) {
    return STANDARDTARIF;
  }
}

/** Gebühr in Cent für eine Parkdauer in Minuten; je angefangene Stunde, höchstens der Tagespreis. */
export function gebuehr(tarif: Tarif, minuten: number): number {
  if (minuten <= tarif.freiminuten) {
    return 0;
  }
  const tage = Math.floor(minuten / (24 * 60));
  const rest = minuten - tage * 24 * 60;
  const restpreis = Math.min(Math.ceil(rest / 60) * tarif.stundenpreis, tarif.tageshoechstpreis);
  return tage * tarif.tageshoechstpreis + restpreis;
}

