import { gebuehr, ladeTarif } from "./gebuehr";

/** Kassenautomat: liest den Tarif beim Start und berechnet je Ticket die Gebühr. */
export class Kasse {
  private readonly tarif = ladeTarif(process.env.TARIF_DATEI ?? "tarif.json");

  betrag(einfahrt: Date, ausfahrt: Date): number {
    const minuten = Math.ceil((ausfahrt.getTime() - einfahrt.getTime()) / 60000);
    return gebuehr(this.tarif, Math.max(minuten, 0));
  }
}

